import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser } from '../services/api';
import { getFranchises, getLoggedInUser } from '../services/api';  // Add a function to get logged-in user's data

const CreateUser = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]); 
  const [editingUser, setEditingUser] = useState(null); 
  const [loggedInUser, setLoggedInUser] = useState(null);  // Store logged-in user info

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchUsers = async () => {
      try {
        const response = await getUsers();
        setUsers(response);
      } catch (error) {
        alert('Error fetching users: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchLoggedInUser = async () => {
      try {
        const userResponse = await getLoggedInUser();  // Function to get logged-in user details (includes role)
        setLoggedInUser(userResponse.data);
      } catch (error) {
        alert('Error fetching logged-in user: ' + (error.response?.data?.message || error.message));
      }
    };

    fetchFranchises();
    fetchUsers();
    fetchLoggedInUser();  // Fetch logged-in user data on mount
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (editingUser) {
        // Check if logged-in user is authorized to update this user
        if (loggedInUser.role !== 'admin' && loggedInUser.role !== 'superadmin') {
          return alert('You do not have permission to update users.');
        }
        await updateUser(editingUser._id, formData);
        alert('User updated successfully!');
      } else {
        // Ensure only admins or superadmins can create a user
        if (loggedInUser.role !== 'admin' && loggedInUser.role !== 'superadmin') {
          return alert('You do not have permission to create users.');
        }
        await createUser(formData);
        alert('User created successfully!');
      }

      setEditingUser(null);
      setFormData({ username: '', password: '', name: '', role: 'user', franchiseId: '' });

      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Error creating/updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      username: user.username,
      password: '', 
      name: user.name,
      role: user.role,
      franchiseId: user.franchiseId || '',
    });
  };

  const handleDelete = async (userId) => {
    try {
      // Check if logged-in user is authorized to delete
      if (loggedInUser.role !== 'admin' && loggedInUser.role !== 'superadmin') {
        return alert('You do not have permission to delete users.');
      }
      await deleteUser(userId);
      alert('User deleted successfully!');
      const response = await getUsers();
      setUsers(response); 
    } catch (error) {
      console.error("Failed to delete user:", error.message);
      alert('Failed to delete user. Please try again.');
    }
  };

  return (
    <div className="create-user-container">
      <h1>{editingUser ? 'Edit User' : 'Create User'}</h1>
      <form onSubmit={handleSubmit} className="form-container">
        {/* Form Fields */}
        {/* Same form elements as in your original code */}

        <button type="submit" className="submit-btn">{editingUser ? 'Update User' : 'Create User'}</button>
      </form>

      <h2>All Users</h2>
      <table className="user-table">
        <thead>
          <tr>
            <th>Username</th>
            <th>Name</th>
            <th>Role</th>
            <th>Franchise</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => {
            const franchiseName = user.franchise ? user.franchise.name : 'N/A';
            return (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>{franchiseName}</td>
                <td>
                  <button onClick={() => handleEdit(user)} className="edit-btn">Edit</button>
                  <button onClick={() => handleDelete(user._id)} className="delete-btn">Delete</button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

export default CreateUser;
